#!/bin/sh
# Entrypoint of the optional Jackett container (compose profile "search"), mounted read-only into the upstream
# linuxserver/jackett image and run as uid 1000 (not root, no s6 init, read-only root filesystem, no capabilities).
#
# On every start it (re)asserts the settings the rest of the stack relies on in /config/Jackett/ServerConfig.json and
# leaves everything else (indexers, Jackett's own admin password, proxy, cache) to the admin:
#   APIKey           = $JACKETT_API_KEY (generated by ./setup.sh --search; the api uses it, it is never shown to users)
#   BasePathOverride = /jackett          (the admin UI is reached through https://APP_HOST/jackett/)
#   Port 9117, AllowExternal             (the vpn sidecar's firewall lets only the api container connect)
#   UpdateDisabled                       (the image is pinned; the root filesystem is read-only anyway)
#   FlareSolverrUrl  = $FLARESOLVERR_URL when set (profile "search-flaresolverr"); our own URL is removed again when unset
# The API key travels through the environment, never through argv (jq reads $ENV).
# POSIX sh; no bashisms.
set -eu
die() { echo "jackett-entrypoint: $*" >&2; exit 1; }

key=${JACKETT_API_KEY:-}
case "$key" in ''|*[!A-Za-z0-9]*) die "JACKETT_API_KEY must be set to 16-128 letters/digits (./setup.sh --search generates it)" ;; esac
[ "${#key}" -ge 16 ] && [ "${#key}" -le 128 ] || die "JACKETT_API_KEY must be 16-128 letters/digits"
fs=${FLARESOLVERR_URL:-}
case "$fs" in ''|http://127.0.0.1:[0-9]|http://127.0.0.1:[0-9][0-9]|http://127.0.0.1:[0-9][0-9][0-9]|http://127.0.0.1:[0-9][0-9][0-9][0-9]|http://127.0.0.1:[0-9][0-9][0-9][0-9][0-9]) ;;
  *) die "FLARESOLVERR_URL must be empty or http://127.0.0.1:<port> (FlareSolverr shares this network namespace)" ;;
esac

dir=/config/Jackett
cfg=$dir/ServerConfig.json
[ ! -L /config ] && [ ! -L "$dir" ] || die "$dir must not be a symlink"
mkdir -p "$dir"
[ -w "$dir" ] || die "$dir is not writable by uid $(id -u) (the jackett-init service fixes the volume's ownership)"
umask 077
tmp=$(mktemp "$dir/.ServerConfig.json.XXXXXX")
trap 'rm -f "$tmp"' EXIT
current='{}'
if [ -f "$cfg" ] && [ ! -L "$cfg" ] && jq -e 'type == "object"' "$cfg" >/dev/null 2>&1; then current=$(cat "$cfg"); fi
printf '%s' "$current" | JACKETT_API_KEY="$key" FS="$fs" jq '
  . + { Port: 9117, AllowExternal: true, APIKey: $ENV.JACKETT_API_KEY, BasePathOverride: "/jackett", BaseUrlOverride: null,
        UpdateDisabled: true, UpdatePrerelease: false }
  | if $ENV.FS != "" then .FlareSolverrUrl = $ENV.FS
    elif ((.FlareSolverrUrl // "") | test("^http://127\\.0\\.0\\.1:[0-9]+/?$")) then .FlareSolverrUrl = null
    else . end' > "$tmp"
mv -f "$tmp" "$cfg"   # rename: replaces a planted link instead of writing through it
trap - EXIT
unset key JACKETT_API_KEY   # Jackett keeps it in ServerConfig.json; it need not linger in its environment
echo "jackett-entrypoint: settings applied (base path /jackett, updates off${fs:+, FlareSolverr $fs})" >&2
exec /app/Jackett/jackett --NoUpdates --NoRestart
